CREATE SCHEMA p06_author_9083ce09efb645f2ad04356b1660483d;
    CREATE TABLE p06_author_9083ce09efb645f2ad04356b1660483d.bundles(company int NOT NULL,digest bytea NOT NULL,bundle bytea NOT NULL,
      PRIMARY KEY(company,digest),CHECK(octet_length(digest)=32 AND digest=sha256(bundle)),
      CHECK(octet_length(bundle) BETWEEN 1 AND 4194304));
    CREATE FUNCTION p06_author_9083ce09efb645f2ad04356b1660483d.immutable_bundle() RETURNS trigger LANGUAGE plpgsql AS $$
      BEGIN RAISE EXCEPTION 'immutable bundle payload'; END $$;
    CREATE TRIGGER immutable_bundle BEFORE UPDATE ON p06_author_9083ce09efb645f2ad04356b1660483d.bundles FOR EACH ROW EXECUTE FUNCTION p06_author_9083ce09efb645f2ad04356b1660483d.immutable_bundle();
    CREATE TABLE p06_author_9083ce09efb645f2ad04356b1660483d.runs(id int PRIMARY KEY,company int NOT NULL,digest bytea NOT NULL,
      FOREIGN KEY(company,digest) REFERENCES p06_author_9083ce09efb645f2ad04356b1660483d.bundles(company,digest) DEFERRABLE INITIALLY DEFERRED);
    INSERT INTO p06_author_9083ce09efb645f2ad04356b1660483d.bundles VALUES(1,sha256('payload'::bytea),'payload'::bytea);

CREATE TABLE p06_author_9083ce09efb645f2ad04356b1660483d.owners(id int PRIMARY KEY);
      CREATE TABLE p06_author_9083ce09efb645f2ad04356b1660483d.executions(id int PRIMARY KEY,owner int REFERENCES p06_author_9083ce09efb645f2ad04356b1660483d.owners(id) ON DELETE CASCADE);
      CREATE TABLE p06_author_9083ce09efb645f2ad04356b1660483d.jobs(id int PRIMARY KEY,execution int REFERENCES p06_author_9083ce09efb645f2ad04356b1660483d.executions(id) DEFERRABLE INITIALLY DEFERRED);
      CREATE TABLE p06_author_9083ce09efb645f2ad04356b1660483d.attempts(id int PRIMARY KEY,job int REFERENCES p06_author_9083ce09efb645f2ad04356b1660483d.jobs(id) ON DELETE CASCADE);
      CREATE TABLE p06_author_9083ce09efb645f2ad04356b1660483d.checkpoints(id int PRIMARY KEY,job int REFERENCES p06_author_9083ce09efb645f2ad04356b1660483d.jobs(id) ON DELETE CASCADE);
      CREATE TABLE p06_author_9083ce09efb645f2ad04356b1660483d.facts(id int PRIMARY KEY,job int REFERENCES p06_author_9083ce09efb645f2ad04356b1660483d.jobs(id) ON DELETE CASCADE,owner int NOT NULL);
      CREATE FUNCTION p06_author_9083ce09efb645f2ad04356b1660483d.immutable_fact() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
        IF TG_OP='DELETE' AND pg_trigger_depth()>1 AND NOT EXISTS(SELECT 1 FROM p06_author_9083ce09efb645f2ad04356b1660483d.owners WHERE id=OLD.owner) THEN RETURN OLD; END IF;
        RAISE EXCEPTION 'append-only fact'; END $$;
      CREATE TRIGGER immutable_fact BEFORE DELETE OR UPDATE ON p06_author_9083ce09efb645f2ad04356b1660483d.facts FOR EACH ROW EXECUTE FUNCTION p06_author_9083ce09efb645f2ad04356b1660483d.immutable_fact();
      CREATE TABLE p06_author_9083ce09efb645f2ad04356b1660483d.usage(id int PRIMARY KEY,owner int REFERENCES p06_author_9083ce09efb645f2ad04356b1660483d.owners(id) ON DELETE CASCADE,job int REFERENCES p06_author_9083ce09efb645f2ad04356b1660483d.jobs(id) ON DELETE CASCADE,amount int);
      CREATE TABLE p06_author_9083ce09efb645f2ad04356b1660483d.archive(id int PRIMARY KEY,amount int);
      INSERT INTO p06_author_9083ce09efb645f2ad04356b1660483d.owners VALUES(1),(2); INSERT INTO p06_author_9083ce09efb645f2ad04356b1660483d.executions VALUES(1,1),(2,2);
      INSERT INTO p06_author_9083ce09efb645f2ad04356b1660483d.jobs VALUES(1,1),(2,2); INSERT INTO p06_author_9083ce09efb645f2ad04356b1660483d.attempts VALUES(1,1),(2,2);
      INSERT INTO p06_author_9083ce09efb645f2ad04356b1660483d.checkpoints VALUES(1,1),(2,2); INSERT INTO p06_author_9083ce09efb645f2ad04356b1660483d.facts VALUES(1,1,1),(2,2,2);
      INSERT INTO p06_author_9083ce09efb645f2ad04356b1660483d.usage VALUES(1,1,1,50),(2,2,2,80);
      BEGIN;
      CREATE TEMP TABLE retiring_jobs ON COMMIT DROP AS SELECT job.id FROM p06_author_9083ce09efb645f2ad04356b1660483d.jobs AS job JOIN p06_author_9083ce09efb645f2ad04356b1660483d.executions AS execution ON execution.id=job.execution WHERE execution.owner=1 FOR UPDATE OF job;
      INSERT INTO p06_author_9083ce09efb645f2ad04356b1660483d.archive SELECT id,amount FROM p06_author_9083ce09efb645f2ad04356b1660483d.usage WHERE owner=1;
      DELETE FROM p06_author_9083ce09efb645f2ad04356b1660483d.owners WHERE id=1;
      DELETE FROM p06_author_9083ce09efb645f2ad04356b1660483d.jobs AS job USING retiring_jobs AS selected WHERE job.id=selected.id;
      COMMIT;
